    [Description("The search query")] string query,
    CancellationToken cancellationToken = default)
{
    // Try Bing Web Search API if a key is available; otherwise fall back to
    // a DuckDuckGo HTML scrape that needs no API key.
    var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "ResearchAgent/1.0 (compatible; bot)");

    if (!string.IsNullOrEmpty(bingKey))
    {
        return await SearchBingAsync(http, bingKey, query, cancellationToken);
    }

    return await SearchDuckDuckGoAsync(http, query, cancellationToken);
}

static async Task<string> SearchBingAsync(
    HttpClient http, string apiKey, string query, CancellationToken ct)
{
    var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
    http.DefaultRequestHeaders.Add("Ocp-Apim-Subscription-Key", apiKey);

    var json = await http.GetStringAsync(url, ct);
    using var doc = JsonDocument.Parse(json);

    var sb = new StringBuilder();
    sb.AppendLine($"Search results for: {query}\n");

    if (doc.RootElement.TryGetProperty("webPages", out var pages)
        && pages.TryGetProperty("value", out var results))
    {
        foreach (var r in results.EnumerateArray())
        {
            var name = r.GetProperty("name").GetString();
            var snippet = r.GetProperty("snippet").GetString();
            var resultUrl = r.GetProperty("url").GetString();
            sb.AppendLine($"- **{name}**");
            sb.AppendLine($"  {snippet}");
            sb.AppendLine($"  Source: {resultUrl}\n");
        }
    }

    return sb.Length > 0 ? sb.ToString() : "No results found.";
}

static async Task<string> SearchDuckDuckGoAsync(
    HttpClient http, string query, CancellationToken ct)
{
    // DuckDuckGo Instant Answer API (JSON, no key required).
    var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
    var json = await http.GetStringAsync(url, ct);
    using var doc = JsonDocument.Parse(json);

    var sb = new StringBuilder();
    sb.AppendLine($"Search results for: {query}\n");

    var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
    var abstractUrl = doc.RootElement.GetProperty("AbstractURL").GetString();
    if (!string.IsNullOrWhiteSpace(abstractText))
    {
        sb.AppendLine($"- {abstractText}");
        sb.AppendLine($"  Source: {abstractUrl}\n");
    }

    if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
    {
        var count = 0;
        foreach (var topic in topics.EnumerateArray())
        {
            if (count >= 5) break;
            if (topic.TryGetProperty("Text", out var text)
                && topic.TryGetProperty("FirstURL", out var topicUrl))
            {
                sb.AppendLine($"- {text.GetString()}");
                sb.AppendLine($"  Source: {topicUrl.GetString()}\n");
                count++;
            }
        }
    }

    return sb.Length > 30 ? sb.ToString() : $"No instant results. Try refining: \"{query}\"";
}

