146. static async Task<string> SearchBingAsync(
147.     HttpClient http, string apiKey, string query, CancellationToken ct)
148. {
149.     var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
150.     http.DefaultRequestHeaders.Add("Ocp-Apim-Subscription-Key", apiKey);
