157. 
158.     if (doc.RootElement.TryGetProperty("webPages", out var pages)
159.         && pages.TryGetProperty("value", out var results))
160.     {
161.         foreach (var r in results.EnumerateArray())
162.         {
163.             var name = r.GetProperty("name").GetString();
164.             var snippet = r.GetProperty("snippet").GetString();
165.             var resultUrl = r.GetProperty("url").GetString();
166.             sb.AppendLine($"- **{name}**");
167.             sb.AppendLine($"  {snippet}");
168.             sb.AppendLine($"  Source: {resultUrl}\n");
169.         }
170.     }
171. 
172.     return sb.Length > 0 ? sb.ToString() : "No results found.";
173. }
