 using System.ComponentModel;
 using System.Text;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // ---------------------------------------------------------------------------
 // Configuration
 // ---------------------------------------------------------------------------
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // ---------------------------------------------------------------------------
 // Shared state for the note-taking tool
 // ---------------------------------------------------------------------------
 var notebook = new ResearchNotebook();

 // ---------------------------------------------------------------------------
 // Tool definitions
 // ---------------------------------------------------------------------------
 var searchTool = AIFunctionFactory.Create(
     SearchWebAsync,
     new AIFunctionFactoryOptions { Name = "search_web", Description = "Search the web for information on a query. Returns a list of result snippets." });

 var addNoteTool = AIFunctionFactory.Create(
     notebook.AddNote,
     new AIFunctionFactoryOptions { Name = "add_note", Description = "Save a research note with a title and body for later reference." });

 var readNotesTool = AIFunctionFactory.Create(
     notebook.ReadNotes,
     new AIFunctionFactoryOptions { Name = "read_notes", Description = "Read all saved research notes." });

 // ---------------------------------------------------------------------------
 // Build IChatClient via MEAI + OpenAI provider
 // ---------------------------------------------------------------------------
 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // ---------------------------------------------------------------------------
 // Create the research agent
 // ---------------------------------------------------------------------------
 var agent = new ChatClientAgent(
     chatClient,
     new ChatClientAgentOptions
     {
         Name = "ResearchAgent",
         Description = "An AI research assistant that searches the web and takes notes.",
         ChatOptions = new ChatOptions
         {
             Instructions = """
                 You are a thorough research assistant. When given a topic:
                 1. Break the topic into 2-3 key search queries.
                 2. Use the search_web tool to find information for each query.
                 3. Use add_note to record the most important findings (cite sources).
                 4. After gathering enough information, use read_notes to review everything.
                 5. Produce a well-structured summary with sections, key findings, and source URLs.
                 Always search before answering. Never fabricate sources.
                 """,
             Tools = [searchTool, addNoteTool, readNotesTool],
             Temperature = 0f,
             MaxOutputTokens = 4096,
         },
     });

 // ---------------------------------------------------------------------------
 // Interactive loop
 // ---------------------------------------------------------------------------
 Console.WriteLine("=== Research Agent ===");
 Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

 var session = await agent.CreateSessionAsync(CancellationToken.None);

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("> ");
     Console.ResetColor();

     var input = Console.ReadLine();
     if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("Researching… (this may take a moment)\n");
     Console.ResetColor();

     notebook.Clear();

     try
     {
         var runOptions = new ChatClientAgentRunOptions();

         var response = await agent.RunAsync(
             input,
             session,
             runOptions,
             CancellationToken.None);

         Console.ForegroundColor = ConsoleColor.Green;
         Console.WriteLine(response.Text);
         Console.ResetColor();
         Console.WriteLine();
     }
     catch (Exception ex)
     {
         Console.ForegroundColor = ConsoleColor.Red;
         Console.WriteLine($"Error: {ex.Message}");
         Console.ResetColor();
     }
 }

 Console.WriteLine("Goodbye!");
 return;

 // ============================================================================
 // Tool implementations
 // ============================================================================

 /// <summary>Search the web for information using the Bing Search API or a fallback.</summary>
 [Description("Search the web for information on a query.")]
 static async Task<string> SearchWebAsync(
     [Description("The search query")] string query,
     CancellationToken cancellationToken = default)
 {
     // Try Bing Web Search API if a key is available; otherwise fall back to
     // a DuckDuckGo HTML scrape that needs no API key.
     var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");

     using var http = new HttpClient();
     http.DefaultRequestHeaders.UserAgent.ParseAdd(
         "ResearchAgent/1.0 (compatible; bot)");

     if (!string.IsNullOrEmpty(bingKey))
     {
         return await SearchBingAsync(http, bingKey, query, cancellationToken);
     }

     return await SearchDuckDuckGoAsync(http, query, cancellationToken);
 }

 static async Task<string> SearchBingAsync(
     HttpClient http, string apiKey, string query, CancellationToken ct)
 {
     var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
     http.DefaultRequestHeaders.Add("Ocp-Apim-Subscription-Key", apiKey);

     var json = await http.GetStringAsync(url, ct);
     using var doc = JsonDocument.Parse(json);

     var sb = new StringBuilder();
     sb.AppendLine($"Search results for: {query}\n");

     if (doc.RootElement.TryGetProperty("webPages", out var pages)
         && pages.TryGetProperty("value", out var results))
     {
         foreach (var r in results.EnumerateArray())
         {
             var name = r.GetProperty("name").GetString();
             var snippet = r.GetProperty("snippet").GetString();
             var resultUrl = r.GetProperty("url").GetString();
             sb.AppendLine($"- **{name}**");
             sb.AppendLine($"  {snippet}");
             sb.AppendLine($"  Source: {resultUrl}\n");
         }
     }

     return sb.Length > 0 ? sb.ToString() : "No results found.";
 }

 static async Task<string> SearchDuckDuckGoAsync(
     HttpClient http, string query, CancellationToken ct)
 {
     // DuckDuckGo Instant Answer API (JSON, no key required).
     var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
     var json = await http.GetStringAsync(url, ct);
     using var doc = JsonDocument.Parse(json);

     var sb = new StringBuilder();
     sb.AppendLine($"Search results for: {query}\n");

     var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
     var abstractUrl = doc.RootElement.GetProperty("AbstractURL").GetString();
     if (!string.IsNullOrWhiteSpace(abstractText))
     {
         sb.AppendLine($"- {abstractText}");
         sb.AppendLine($"  Source: {abstractUrl}\n");
     }

     if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
     {
         var count = 0;
         foreach (var topic in topics.EnumerateArray())
         {
             if (count >= 5) break;
             if (topic.TryGetProperty("Text", out var text)
                 && topic.TryGetProperty("FirstURL", out var topicUrl))
             {
                 sb.AppendLine($"- {text.GetString()}");
                 sb.AppendLine($"  Source: {topicUrl.GetString()}\n");
                 count++;
             }
         }
     }

     return sb.Length > 30 ? sb.ToString() : $"No instant results. Try refining: \"{query}\"";
 }

 // ============================================================================
 // Notebook (in-memory note store)
 // ============================================================================

 sealed class ResearchNotebook
 {
     private readonly List<(string Title, string Body)> _notes = [];

     [Description("Save a research note.")]
     public string AddNote(
         [Description("Short title for the note")] string title,
         [Description("Detailed content of the note")] string body)
     {
         _notes.Add((title, body));
         return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
     }

     [Description("Read all saved research notes.")]
     public string ReadNotes()
     {
         if (_notes.Count == 0)
             return "No notes yet.";

         var sb = new StringBuilder();
         for (var i = 0; i < _notes.Count; i++)
         {
             sb.AppendLine($"## Note {i + 1}: {_notes[i].Title}");
             sb.AppendLine(_notes[i].Body);
             sb.AppendLine();
         }

         return sb.ToString();
     }

     public void Clear() => _notes.Clear();
 }
